import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.cZsgxozV.js";var i=JSON.parse(`{"title":"Android sideload (Tauri APK)","description":"","frontmatter":{},"headers":[],"relativePath":"desktop/android-sideload.md","filePath":"desktop/android-sideload.md"}`),a={name:`desktop/android-sideload.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="android-sideload-tauri-apk" tabindex="-1">Android sideload (Tauri APK) <a class="header-anchor" href="#android-sideload-tauri-apk" aria-label="Permalink to “Android sideload (Tauri APK)”">​</a></h1><p>DocuHaim Android is a <strong>Tauri v2</strong> shell around the same SPA. It is <strong>not</strong> distributed on Google Play. Install the APK from the unified GitHub Release.</p><h2 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to “Releases”">​</a></h2><table tabindex="0"><thead><tr><th>Channel</th><th>Workflow</th><th>Tag</th><th>Artifacts</th></tr></thead><tbody><tr><td>Unified (preferred)</td><td><code>.github/workflows/release-tauri.yml</code></td><td><code>vX.Y.Z</code></td><td>DMG / NSIS / APK / <code>latest.json</code></td></tr><tr><td>Android-only (optional)</td><td><code>.github/workflows/release-tauri-android.yml</code></td><td><code>vX.Y.Z</code> (same)</td><td>debug-signed APK only (<code>make_latest: false</code>)</td></tr></tbody></table><p>Android APKs ship on the <strong>same</strong> <code>vX.Y.Z</code> release as desktop. Do <strong>not</strong> publish separate <code>android-v*</code> tags — GitHub <code>/releases/latest</code> would point at them and break desktop auto-update (<code>latest.json</code> 404).</p><p>CI builds <strong><code>tauri android build --debug --apk</code></strong> so the published APK is sideload-installable without a release keystore.</p><h3 id="publish-normal" tabindex="-1">Publish (normal) <a class="header-anchor" href="#publish-normal" aria-label="Permalink to “Publish (normal)”">​</a></h3><ol><li>Actions → <strong>Release Tauri</strong> → Run workflow.</li><li>Download DMG / EXE / APK from the new <code>v…</code> release (also linked from <a href="https://github.com/explainpark101/DocuHaim/releases/latest" target="_blank" rel="noreferrer">releases/latest</a>).</li></ol><h3 id="publish-apk-only-rebuild" tabindex="-1">Publish APK only (rebuild) <a class="header-anchor" href="#publish-apk-only-rebuild" aria-label="Permalink to “Publish APK only (rebuild)”">​</a></h3><ol><li>Actions → <strong>Release Tauri Android</strong> → Run workflow.</li><li>Optional <code>version</code> input (defaults to root <code>package.json</code> version). Uploads to <code>vX.Y.Z</code> without changing which release is “Latest”.</li></ol><h2 id="install-sideload" tabindex="-1">Install (sideload) <a class="header-anchor" href="#install-sideload" aria-label="Permalink to “Install (sideload)”">​</a></h2><ol><li>On the phone, allow install from the browser/Files app (“unknown apps”).</li><li>Open the downloaded <code>.apk</code> and install.</li><li>First launch: unlock with master password and/or <strong>생체 인식</strong> (platform biometric via Stronghold — not browser WebAuthn/PRF).</li></ol><h2 id="features-on-android" tabindex="-1">Features on Android <a class="header-anchor" href="#features-on-android" aria-label="Permalink to “Features on Android”">​</a></h2><ul><li><strong>S3 / WebDAV</strong> — same encrypted credential flow; secrets in Stronghold (app-private).</li><li><strong>Local Haim</strong> — default vault under app data (<code>LocalHaim</code>). You can also pick another folder via the system dialog when available.</li><li><strong><code>.md</code> / <code>.markdown</code> file association</strong> — open markdown from Files / other apps with DocuHaim (vault note if under the Local root, otherwise session workspace).</li><li><strong>Advanced Search</strong> — filename / path / commands only; Lucivy inverted index is disabled.</li><li><strong>share_target</strong> — existing PWA share intake is assumed to keep working; this shell does not reimplement it.</li></ul><h2 id="local-development" tabindex="-1">Local development <a class="header-anchor" href="#local-development" aria-label="Permalink to “Local development”">​</a></h2><p>Requires Android SDK + NDK, <strong>JDK 17</strong>, and Rust Android targets.<br><code>bun run tauri:android:*</code> uses <a href="../../scripts/tauri-android.mjs"><code>scripts/tauri-android.mjs</code></a> to set <code>JAVA_HOME</code> (Homebrew OpenJDK) so Gradle does not hit macOS’s “Unable to locate a Java Runtime” stub.</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Sideload-ready (debug-signed) — recommended for device install without a release keystore</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri:android:build:debug</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Release APK (needs signingConfig / keystore — otherwise unsigned and will not install)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri:android:build</span></span></code></pre></div><p>APK output: <code>src-tauri/gen/android/app/build/outputs/apk/</code>.<br> Project files: <code>src-tauri/gen/android/</code>. Intent filters come from <a href="../../src-tauri/tauri.conf.json"><code>src-tauri/tauri.conf.json</code></a> <code>bundle.fileAssociations</code>.</p><h2 id="signing" tabindex="-1">Signing <a class="header-anchor" href="#signing" aria-label="Permalink to “Signing”">​</a></h2><p>GitHub Release Android APKs are <strong>debug-signed</strong> (same idea as local <code>tauri:android:build:debug</code>). Plain <code>tauri:android:build</code> (release, no keystore) can produce an unsigned APK that Android rejects (“패키지가 잘못되어…”). For private release signing later, configure Gradle <code>signingConfig</code> / CI secrets and switch the workflow off <code>--debug</code>.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to “Out of scope”">​</a></h2><ul><li>Google Play / AAB</li><li>iOS</li><li>Browser WebAuthn PRF in the Android WebView (platform biometric only)</li></ul>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};